# Parse the table and include ALL function rows, including Undistributed offsetting receipts

with open('/app/resources/treasury_bulletin_1981_12.txt', 'r') as f:
    content = f.read()

lines = content.split('\n')

# Find the table
in_table = False
table_lines = []
for line in lines:
    if '| Function | Oct. |' in line:
        in_table = True
    if in_table:
        table_lines.append(line)
        if 'Source:' in line:
            break

# Extract all Total/Totals rows (including negative values)
functions_data = {}

for line in table_lines:
    # Look for Total rows
    if ('| Total |' in line or '| Totals |' in line) and 'Undistributed' not in line and 'Net budget' not in line:
        parts = line.split('|')
        # Get the function name from earlier rows
        func_name = None
        for prev_line in table_lines:
            if '| Total |' in prev_line or '| Totals |' in prev_line:
                continue
            if prev_line == line:
                break
            # Look for the header above this total
            if '| ' in prev_line and 'nan' in prev_line:
                func_name = prev_line.split('|')[1].strip()
                break

        values = []
        for i in range(2, 14):
            val_str = parts[i].strip().replace(',', '').replace('-', '')
            try:
                # Handle negative values - check if original had negative
                if '-' in parts[i] and parts[i].strip() != '-':
                    val = -int(val_str)
                else:
                    val = int(val_str)
                values.append(val)
            except:
                pass

        if len(values) == 12:
            print(f"Function: {line[:50]}... Values: {values[:3]}...{values[-3:]}")

# More direct approach - look for the actual data lines
print("\n" + "="*60)
print("Direct extraction of all Total/Totals rows:")

import re

# Get all lines with Total/Totals that have numeric data
all_totals = []
for line in table_lines:
    if ('| Total |' in line or '| Totals |' in line):
        # Skip if it's the Net budget outlays row
        if 'Net budget' in line:
            continue
        # Check if it has numeric data
        parts = line.split('|')
        try:
            # Check columns 2-13 for valid numbers
            values = []
            for i in range(2, 14):
                val_str = parts[i].strip().replace(',', '')
                if val_str and val_str != 'nan' and val_str != '-':
                    # Handle the 7-704 format (debit/credit)
                    if val_str.startswith('7'):
                        val_str = val_str[1:]
                    val = int(val_str)
                    # Check if originally negative
                    if '-' in parts[i]:
                        val = -val
                    values.append(val)

            if len(values) == 12:
                # Get function name
                func_line_idx = table_lines.index(line) - 1
                func_name = ""
                while func_line_idx >= 0:
                    check_line = table_lines[func_line_idx]
                    if '|' in check_line and 'nan' in check_line:
                        func_name = check_line.split('|')[1].strip()
                        break
                    func_line_idx -= 1

                all_totals.append((func_name, values))
                print(f"{func_name}: {values}")
        except Exception as e:
            pass

print(f"\nTotal function categories found: {len(all_totals)}")

# Combine all values
all_values = []
for func_name, vals in all_totals:
    all_values.extend(vals)

print(f"Total values: {len(all_values)}")

# Calculate population standard deviation
mean = sum(all_values) / len(all_values)
variance = sum((x - mean) ** 2 for x in all_values) / len(all_values)
pop_std = variance ** 0.5

print(f"\nMean: {mean:.2f}")
print(f"Population standard deviation: {round(pop_std, 2)}")
EOF
